// A small fake API, so this exercise works in the browser without a server.
// Do not edit this file. The tests replace the whole module with a mock, so
// none of this code runs during the tests.
//
// fetchUsers(page, { signal }) returns a Promise:
// - it resolves to an array of { id, name } objects for page 1 or page 2
// - it rejects with an Error when the request fails (about one request in four)
// - it rejects with an AbortError if you pass an AbortSignal as { signal }
//   and abort it before the answer arrives
//
// Page 1 answers slowly and page 2 answers quickly. Click "Page 1" and then
// "Page 2" straight away in the playground: the answers arrive out of order.

const USERS_BY_PAGE = {
  1: [
    { id: 1, name: 'Ada Lovelace' },
    { id: 2, name: 'Alan Turing' },
    { id: 3, name: 'Grace Hopper' },
    { id: 4, name: 'Linus Torvalds' },
  ],
  2: [
    { id: 5, name: 'Margaret Hamilton' },
    { id: 6, name: 'Dennis Ritchie' },
    { id: 7, name: 'Barbara Liskov' },
    { id: 8, name: 'Tim Berners-Lee' },
  ],
}

const DELAY_MS = { 1: 1500, 2: 400 }
const FAILURE_RATE = 0.25

function abortError() {
  return new DOMException('The request was aborted', 'AbortError')
}

export function fetchUsers(page, { signal } = {}) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortError())
      return
    }

    const timer = setTimeout(() => {
      const users = USERS_BY_PAGE[page]
      if (!users) {
        reject(new Error(`Page ${page} does not exist`))
      } else if (Math.random() < FAILURE_RATE) {
        reject(new Error('Network error, please try again'))
      } else {
        resolve(users)
      }
    }, DELAY_MS[page] ?? 500)

    signal?.addEventListener(
      'abort',
      () => {
        clearTimeout(timer)
        reject(abortError())
      },
      { once: true },
    )
  })
}
